using Microsoft.VisualStudio.TestTools.UnitTesting;
using Payments;

namespace PaymentGateway.Tests;

[TestClass]
public sealed class PaymentGatewayTests
{
    private Payments.PaymentGateway _sut = null!;

    [TestInitialize]
    public void Setup()
    {
        _sut = new Payments.PaymentGateway();
    }

    // ──────────────────────────────────────────────
    //  ChargeAsync – valid inputs
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow("tok_valid_visa", 10.00, DisplayName = "Standard amount")]
    [DataRow("tok_valid_mc", 0.01, DisplayName = "Minimum positive amount")]
    [DataRow("tok_valid_amex", 999999.99, DisplayName = "Large amount")]
    public async Task ChargeAsync_ValidTokenAndPositiveAmount_ThrowsNotImplementedException(
        string cardToken, double amountDouble)
    {
        // Arrange
        var amount = (decimal)amountDouble;

        // Act & Assert
        await Assert.ThrowsExceptionAsync<NotImplementedException>(
            () => _sut.ChargeAsync(cardToken, amount));
    }

    // ──────────────────────────────────────────────
    //  ChargeAsync – null / empty / whitespace token
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow(null, 50.00, DisplayName = "Null token")]
    [DataRow("", 50.00, DisplayName = "Empty token")]
    [DataRow("   ", 50.00, DisplayName = "Whitespace-only token")]
    public async Task ChargeAsync_InvalidToken_ThrowsNotImplementedException(
        string? cardToken, double amountDouble)
    {
        // Arrange
        var amount = (decimal)amountDouble;

        // Act & Assert
        await Assert.ThrowsExceptionAsync<NotImplementedException>(
            () => _sut.ChargeAsync(cardToken!, amount));
    }

    // ──────────────────────────────────────────────
    //  ChargeAsync – zero and negative amounts
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow("tok_valid", 0.00, DisplayName = "Zero amount")]
    [DataRow("tok_valid", -1.00, DisplayName = "Negative amount")]
    [DataRow("tok_valid", -999.99, DisplayName = "Large negative amount")]
    public async Task ChargeAsync_ZeroOrNegativeAmount_ThrowsNotImplementedException(
        string cardToken, double amountDouble)
    {
        // Arrange
        var amount = (decimal)amountDouble;

        // Act & Assert
        await Assert.ThrowsExceptionAsync<NotImplementedException>(
            () => _sut.ChargeAsync(cardToken, amount));
    }

    // ──────────────────────────────────────────────
    //  RefundAsync – valid charge ID
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow("ch_abc123", DisplayName = "Standard charge ID")]
    [DataRow("ch_00000000", DisplayName = "Zeroed charge ID")]
    [DataRow("ch_LongIdWith_Special-Chars.Here", DisplayName = "Complex charge ID")]
    public async Task RefundAsync_ValidChargeId_ThrowsNotImplementedException(string chargeId)
    {
        // Act & Assert
        await Assert.ThrowsExceptionAsync<NotImplementedException>(
            () => _sut.RefundAsync(chargeId));
    }

    // ──────────────────────────────────────────────
    //  RefundAsync – null / empty / whitespace ID
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow(null, DisplayName = "Null charge ID")]
    [DataRow("", DisplayName = "Empty charge ID")]
    [DataRow("   ", DisplayName = "Whitespace-only charge ID")]
    public async Task RefundAsync_InvalidChargeId_ThrowsNotImplementedException(string? chargeId)
    {
        // Act & Assert
        await Assert.ThrowsExceptionAsync<NotImplementedException>(
            () => _sut.RefundAsync(chargeId!));
    }

    // ──────────────────────────────────────────────
    //  Record types – ChargeResult
    // ──────────────────────────────────────────────

    [TestMethod]
    public void ChargeResult_Constructor_SetsProperties()
    {
        // Arrange & Act
        var result = new ChargeResult("ch_123", true);

        // Assert
        Assert.AreEqual("ch_123", result.ChargeId);
        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public void ChargeResult_WithFailure_SetsSuccessToFalse()
    {
        // Arrange & Act
        var result = new ChargeResult("ch_fail", false);

        // Assert
        Assert.AreEqual("ch_fail", result.ChargeId);
        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public void ChargeResult_Equality_TwoIdenticalInstances_AreEqual()
    {
        // Arrange
        var a = new ChargeResult("ch_eq", true);
        var b = new ChargeResult("ch_eq", true);

        // Act & Assert
        Assert.AreEqual(a, b);
    }

    [TestMethod]
    public void ChargeResult_Equality_DifferentChargeId_AreNotEqual()
    {
        // Arrange
        var a = new ChargeResult("ch_1", true);
        var b = new ChargeResult("ch_2", true);

        // Act & Assert
        Assert.AreNotEqual(a, b);
    }

    [TestMethod]
    public void ChargeResult_Equality_DifferentSuccess_AreNotEqual()
    {
        // Arrange
        var a = new ChargeResult("ch_1", true);
        var b = new ChargeResult("ch_1", false);

        // Act & Assert
        Assert.AreNotEqual(a, b);
    }

    // ──────────────────────────────────────────────
    //  Record types – RefundResult
    // ──────────────────────────────────────────────

    [TestMethod]
    public void RefundResult_Constructor_SetsProperties()
    {
        // Arrange & Act
        var result = new RefundResult("re_456", true);

        // Assert
        Assert.AreEqual("re_456", result.RefundId);
        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public void RefundResult_WithFailure_SetsSuccessToFalse()
    {
        // Arrange & Act
        var result = new RefundResult("re_fail", false);

        // Assert
        Assert.AreEqual("re_fail", result.RefundId);
        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public void RefundResult_Equality_TwoIdenticalInstances_AreEqual()
    {
        // Arrange
        var a = new RefundResult("re_eq", true);
        var b = new RefundResult("re_eq", true);

        // Act & Assert
        Assert.AreEqual(a, b);
    }

    [TestMethod]
    public void RefundResult_Equality_DifferentRefundId_AreNotEqual()
    {
        // Arrange
        var a = new RefundResult("re_1", true);
        var b = new RefundResult("re_2", true);

        // Act & Assert
        Assert.AreNotEqual(a, b);
    }

    [TestMethod]
    public void RefundResult_Equality_DifferentSuccess_AreNotEqual()
    {
        // Arrange
        var a = new RefundResult("re_1", true);
        var b = new RefundResult("re_1", false);

        // Act & Assert
        Assert.AreNotEqual(a, b);
    }
}

